('141aeb01-5f5f-5bd5-b726-43731d38742b','65c8ceb3-7b39-5764-ad30-2b09c4209c14',1,'noun','C1','S3','W2',null,'[{"phrase":"proportional representation","register":null,"definition_en":"a system of voting in elections by which all political parties are represented in the government according to the number of votes they receive in the whole country","translation":"سیستم رای گیری در انتخابات که به موجب آن همه احزاب سیاسی با توجه به تعداد آرایی که در کل کشور دریافت می کنند در دولت نمایندگی می شوند.","example":"","example_translation":"","example_audio_url":""},{"phrase":"make false representations","register":"law","definition_en":"to describe or explain something in a way that you know is not true","translation":"توصیف یا توضیح چیزی به روشی که می دانید درست نیست","example":"","example_translation":"","example_audio_url":""}]'::jsonb),
