('ba8d6d45-a004-5507-b153-e60e63a19e7c','141aeb01-5f5f-5bd5-b726-43731d38742b',1,null,null,'spoken & written','when you have someone to speak, vote , or make decisions for you','[ uncountable ]','proportional representation','نمایندگی، وکالت؛ نمایندگی (سیاسی)؛ تمثیل (نمایش)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Minority groups need more effective parliamentary representation.","translation":"گروه های اقلیت به نمایندگی پارلمانی مؤثرتری نیاز دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000776910.mp3"},{"sentence":"There has been a decline in union representation in the auto industry.","translation":"حضور اتحادیه در صنعت خودرو کاهش یافته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001607437.mp3"}]'::jsonb,2),
('4eaa596a-413d-518c-b507-dc50016c9b8d','141aeb01-5f5f-5bd5-b726-43731d38742b',2,null,null,'spoken & written','a painting , sign, description etc that shows something','[ countable ]',null,'یک نقاشی، علامت، توصیف و غیره که چیزی را نشان می دهد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The clock in the painting is a symbolic representation of the passage of time.","translation":"ساعت در نقاشی نمادی از گذر زمان است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000776924.mp3"}]'::jsonb,1),
('6b87565e-439a-5714-bbc4-dfbf0c03c783','141aeb01-5f5f-5bd5-b726-43731d38742b',3,null,null,'spoken & written','the act of representing someone or something','[ uncountable ]',null,'عمل به نمایندگی از کسی یا چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She received praise for her effective representation of Garcia during the trial.","translation":"او به خاطر نمایندگی مؤثرش از گارسیا در طول محاکمه مورد تحسین قرار گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001607438.mp3"}]'::jsonb,1),
('5598214d-acce-5da2-bfde-25e489ff211e','141aeb01-5f5f-5bd5-b726-43731d38742b',4,null,null,'formal','a formal complaint or statement','[ countable usually plural ]',null,'یک شکایت یا بیانیه رسمی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"A group of students made representations to the college about the poor standard of the accommodation.","translation":"گروهی از دانشجویان در مورد استاندارد ضعیف محل اقامت به کالج اظهار نظر کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000776934.mp3"}]'::jsonb,1),
('a3838566-626a-5b63-96b2-bc418fa32996','141aeb01-5f5f-5bd5-b726-43731d38742b',5,null,null,'spoken & written',null,null,'make false representations','نمایندگی، وکالت؛ نمایندگی (سیاسی)؛ تمثیل (نمایش)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('5fe79240-6475-54da-9bcf-3025f43f42da','79ca9f21-5b7e-579d-b8e0-378eebf71ddd',1,null,null,'spoken & written','someone who has been chosen to speak , vote , or make decisions for someone else',null,null,'نماینده، وکیل (کسی)؛ نماینده (شرکت)؛ عضو (نماینده)',array['delegate']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a union representative","translation":"یک نماینده اتحادیه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001607455.mp3"},{"sentence":"an elected representative of the people","translation":"نماینده منتخب مردم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000776991.mp3"}]'::jsonb,2),
('3f20d4fb-b533-5f4f-87ba-82d245923b2b','79ca9f21-5b7e-579d-b8e0-378eebf71ddd',2,null,null,'spoken & written',null,null,'Representative','نماینده، وکیل (کسی)؛ نماینده (شرکت)؛ عضو (نماینده)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('dd68a278-0037-53b6-9cfb-06aa3e422d94','2f2469e7-c623-5a96-845d-41acae514de9',1,null,null,'spoken & written','a member of the House of Representatives, the Lower House of Congress in the United States',null,null,'عضو مجلس نمایندگان، مجلس سفلی کنگره در ایالات متحده','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('191a3474-9ed5-5895-abaa-720fd869c9aa','a43b8673-5c77-52a8-bcad-3b650f4762c8',1,null,null,'spoken & written','typical of a particular group or thing',null,null,'معمولی یک گروه یا چیز خاص','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The latest incident is representative of a wider trend.","translation":"آخرین حادثه نشان دهنده روند گسترده تری است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000776972.mp3"}]'::jsonb,1),
('cbd2d6e1-053c-514f-bcb1-d9fef77a5182','a43b8673-5c77-52a8-bcad-3b650f4762c8',2,null,null,'spoken & written','including examples of all the different types of something in a group',null,null,'از جمله نمونه هایی از انواع مختلف چیزی در یک گروه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The pollsters asked a representative sample of New York residents for their opinions.","translation":"نظرسنجی ها از نمونه ای نماینده از ساکنان نیویورک نظر خود را خواستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001607451.mp3"}]'::jsonb,1),
('13ec7d47-5c98-596e-bed6-1a3f5d27b3a2','a43b8673-5c77-52a8-bcad-3b650f4762c8',3,null,null,'spoken & written','a representative system of government allows people to vote for other people to represent them in the government',null,null,'یک سیستم نمایندگی دولتی به مردم اجازه می دهد تا به افراد دیگر رای دهند تا نماینده آنها در دولت باشند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a representative democracy","translation":"دموکراسی نمایندگی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000776976.mp3"}]'::jsonb,1),
('bfb3a1ac-3a80-5c37-ba8c-3cace6682b83','23435fb5-9cb5-504b-a6b5-fa184daf190a',1,null,null,'spoken & written','a duty to be in charge of someone or something, so that you make decisions and can be blamed if something bad happens','[ uncountable ]',null,'مسئولیت، مسئولیت (نمونه)؛ تکلیف؛ مسئولیت (فرد)','{}'::text[],'{}'::text[],array['have responsibility for (doing) something The Council has responsibility for maintaining the streetlights.','take responsibility for (doing) something Who do you trust to take responsibility for our country''s defence?','take on responsibility ( also assume responsibility formal ) (= start to have responsibility for something ) These days men tend to take on more responsibility at home. The government must assume greater responsibility for the care of the elderly.','shoulder responsibility (= agree to start having a difficult or unpleasant duty ) The city, she said, would shoulder responsibility for caring for the children.','shirk responsibility (= not accept a duty you should accept ) He doesn''t shirk responsibility.','exercise responsibility formal (= take action because you have responsibility for something ) The citizens of ancient Athens met here to exercise their responsibility to govern themselves.','abdicate responsibility formal (= refuse to have responsibility for something you used to have responsibility for ) The state should not allow parents to abdicate responsibility for their children.','the responsibility lies with somebody (= they are responsible for it ) Ultimate responsibility for admissions lies with the Course Co-ordinator.','personal responsibility So far, no one had taken personal responsibility for the project.','overall responsibility The Department of Education has overall responsibility for schools and universities.','direct responsibility (= when no other person is involved ) He has direct responsibility for all the programmes on Radio 1.','sole responsibility (= not shared with others ) The financial director has sole responsibility for financial matters.','collective responsibility (= shared equally by a group of people ) Head teachers should encourage a sense of collective responsibility among teachers.','primary responsibility (= most important responsibility ) I have primary responsibility for the children.','ultimate responsibility (= responsibility for making a final decision ) The National Assembly will have ultimate responsibility for ensuring that health targets are met.','a burden of responsibility (= a lot of responsibility, that worries you ) Being the only wage earner put a great burden of responsibility on my father.','a position of responsibility (= a job in which people depend on you to tell them what they should do ) Before the age of 21 he had attained a position of responsibility in the factory.']::text[],'[{"sentence":"Kelly’s promotion means more money and more responsibility.","translation":"ارتقای کلی به معنای پول بیشتر و مسئولیت بیشتر است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745970.mp3"},{"sentence":"The Minister has responsibility for the National Health Service.","translation":"وزیر مسئول خدمات بهداشتی ملی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa001340.mp3"},{"sentence":"a manager with responsibility for over 100 staff","translation":"مدیری با مسئولیت بیش از 100 پرسنل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001769116.mp3"},{"sentence":"It’s your responsibility to inform us of any changes.","translation":"این مسئولیت شماست که ما را از هرگونه تغییر مطلع کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001769119.mp3"}]'::jsonb,4),
('1728be82-5e91-54c4-a298-e648872b3258','23435fb5-9cb5-504b-a6b5-fa184daf190a',2,null,null,'spoken & written','blame for something bad that has happened','[ uncountable ]',null,'سرزنش برای اتفاق بدی که اتفاق افتاده است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The firm is denying all responsibility .","translation":"این شرکت تمام مسئولیت را رد می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa040185.mp3"},{"sentence":"No one wants to take responsibility for the problem.","translation":"هیچ کس نمی خواهد مسئولیت مشکل را بپذیرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa040186.mp3"},{"sentence":"The surgeon accepted full responsibility for the error that led to her death.","translation":"جراح مسئولیت کامل اشتباهی که منجر به مرگ او شد را پذیرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa040187.mp3"},{"sentence":"So far no one has claimed responsibility (= said that they are responsible ) for the bombings.","translation":"تاکنون هیچ کس مسئولیت این بمب گذاری ها را بر عهده نگرفته است (= گفته است که آنها مسئول هستند).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa040188.mp3"}]'::jsonb,4),
('a9e5e578-0065-5194-a2c7-b02027fb82d7','23435fb5-9cb5-504b-a6b5-fa184daf190a',3,null,null,'spoken & written','something that you must do as part of your job or duty','[ countable ]',null,'کاری که باید به عنوان بخشی از کار یا وظیفه خود انجام دهید','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"My responsibilities include answering the phone and dealing with customer enquiries.","translation":"مسئولیت های من شامل پاسخ دادن به تلفن و رسیدگی به سوالات مشتریان است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000745991.mp3"},{"sentence":"a single parent struggling to balance work and family responsibilities","translation":"یک والدین مجرد که در تلاش برای ایجاد تعادل بین مسئولیت های کاری و خانوادگی است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001563052.mp3"}]'::jsonb,2),
('8e00800d-d7c2-58ec-b117-d3a4c9cda7e3','23435fb5-9cb5-504b-a6b5-fa184daf190a',4,null,null,'spoken & written','something that you ought to do because it is morally or socially right','[ countable ]',null,'کاری که باید انجام دهید زیرا از نظر اخلاقی یا اجتماعی درست است',array['duty']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We all have a responsibility to protect the environment.","translation":"همه ما در حفظ محیط زیست مسئولیت داریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001563056.mp3"},{"sentence":"Parents need to encourage a sense of responsibility in their children (= the ability to behave sensibly in a way that will not harm themselves or other people ) .","translation":"والدین باید احساس مسئولیت را در فرزندان خود تشویق کنند (= توانایی رفتار معقولانه به گونه ای که به خود یا دیگران آسیب نرساند).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001769134.mp3"},{"sentence":"The company saw it as part of its social responsibility to provide education for its workers.","translation":"این شرکت آن را بخشی از مسئولیت اجتماعی خود برای ارائه آموزش برای کارگران خود می دانست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001563060.mp3"}]'::jsonb,3),
